content_map["glucose_monitoring.txt"] = (
    "TITRE: Comment utiliser un glucometre\n"
    "Se laver les mains avant le test. Piquer le doigt sur le cote, pas au\n"
    "centre, pour moins de douleur. Appliquer la goutte de sang sur la\n"
    "bandelette test. Noter le resultat avec la date et l'heure, idealement\n"
    "dans un carnet de suivi ou une application.\n"
    "DARIJA: \u0642\u0628\u0644 \u0645\u0627 \u062a\u0639\u0645\u0644 \u0627\u0644\u062a\u062d\u0644\u064a\u0644\u060c \u0627\u063a\u0633\u0644 \u064a\u062f\u064a\u0643. \u0648\u062e\u0632 \u0641\u064a \u062c\u0646\u0628 \u0627\u0644\u0635\u0628\u0639 \u0645\u0648\u0634 \u0641\u064a \u0627\u0644\u0648\u0633\u0637 \u0628\u0627\u0634 \u064a\u0648\u062c\u0639\u0643 \u0623\u0642\u0644. \u062d\u0637 \u0627\u0644\u0646\u0642\u0637\u0629 \u0639\u0644\u0649 \u0627\u0644\u0634\u0631\u064a\u0637. \u0643\u062a\u0628 \u0627\u0644\u0646\u062a\u064a\u062c\u0629 \u0645\u0639 \u0627\u0644\u0648\u0642\u062a \u0648\u0627\u0644\u062a\u0627\u0631\u064a\u062e \u0628\u0627\u0634 \u062a\u0642\u062f\u0631 \u062a\u062a\u0628\u0639 \u062d\u0627\u0644\u062a\u0643.\n"
    "\n"
    "TITRE: Valeurs normales et seuils d'alerte\n"
    "A jeun, une glycemie normale se situe generalement entre 0.70 et 1.10\n"
    "g/L. Une valeur en dessous de 0.60 g/L est consideree comme une\n"
    "hypoglycemie necessitant une action rapide. Une valeur au-dessus de 2.00\n"
    "g/L de facon repetee doit etre signalee au medecin. Ces seuils peuvent\n"
    "varier selon la prescription individuelle.\n"
    "DARIJA: \u0639\u0627\u062f\u0629 \u0627\u0644\u0633\u0643\u0631 \u0627\u0644\u0637\u0628\u064a\u0639\u064a \u0648\u0642\u062a \u0627\u0644\u0635\u0648\u0645 \u064a\u0643\u0648\u0646 \u0628\u064a\u0646 0.70 \u0648 1.10. \u0643\u0627\u0646 \u0627\u0644\u0631\u0642\u0645 \u062a\u062d\u062a 0.60 \u0647\u0630\u0627 \u0627\u0646\u062e\u0641\u0627\u0636 \u0641\u064a \u0627\u0644\u0633\u0643\u0631 \u0648\u062e\u0627\u0635\u0643 \u062a\u062a\u0635\u0631\u0641 \u0628\u0633\u0631\u0639\u0629. \u0643\u0627\u0646 \u0627\u0644\u0631\u0642\u0645 \u0641\u0648\u0642 2.00 \u0628\u0635\u0641\u0629 \u0645\u062a\u0643\u0631\u0631\u0629\u060c \u0644\u0627\u0632\u0645 \u062a\u0642\u0648\u0644\u0647\u0627 \u0644\u0637\u0628\u064a\u0628\u0643. \u0627\u0644\u0623\u0631\u0642\u0627\u0645 \u0647\u0630\u0648\u0645 \u0645\u0645\u0643\u0646 \u062a\u062a\u0628\u062f\u0644 \u062d\u0633\u0628 \u0627\u0644\u0648\u0635\u0641\u0629 \u0627\u0644\u0637\u0628\u064a\u0629.\n"
    "\n"
    "TITRE: Frequence recommandee des tests\n"
    "La frequence des tests depend du traitement et de la stabilite de la\n"
    "glycemie. Pour un traitement oral stable, un test quelques fois par\n"
    "semaine peut suffire. En debut de traitement ou en cas de changement de\n"
    "dose, des tests plus frequents (quotidiens) sont souvent recommandes par\n"
    "le medecin.\n"
    "DARIJA: \u0639\u062f\u062f \u0645\u0631\u0627\u062a \u0627\u0644\u062a\u062d\u0644\u064a\u0644 \u064a\u062a\u0639\u0644\u0642 \u0628\u0627\u0644\u0639\u0644\u0627\u062c \u0648\u0627\u0633\u062a\u0642\u0631\u0627\u0631 \u0627\u0644\u0633\u0643\u0631. \u0643\u0627\u0646 \u0627\u0644\u0639\u0644\u0627\u062c \u0645\u0633\u062a\u0642\u0631\u060c \u0627\u0644\u062a\u062d\u0644\u064a\u0644 \u0634\u0648\u064a\u0629 \u0641\u064a \u0627\u0644\u062c\u0645\u0639\u0629 \u064a\u0643\u0641\u064a. \u0643\u0627\u0646 \u062a\u0648\u0629 \u0628\u062f\u064a\u062a \u0641\u064a \u0627\u0644\u0639\u0644\u0627\u062c \u0623\u0648 \u0628\u062f\u0644\u062a \u0627\u0644\u062c\u0631\u0639\u0629\u060c \u0627\u0644\u0637\u0628\u064a\u0628 \u0639\u0627\u062f\u0629 \u064a\u0646\u0635\u062d \u062a\u062d\u0644\u064a\u0644 \u0643\u0644 \u064a\u0648\u0645.\n"
)

content_map["side_effects_detailed.txt"] = (
    "TITRE: Troubles digestifs persistants\n"
    "Si les troubles digestifs (nausees, diarrhee) persistent au-dela de\n"
    "deux a trois semaines malgre la prise pendant les repas, le medecin\n"
    "peut ajuster la dose progressivement ou prescrire une forme a liberation\n"
    "prolongee, souvent mieux toleree.\n"
    "DARIJA: \u0643\u0627\u0646 \u0645\u0634\u0627\u0643\u0644 \u0627\u0644\u0645\u0639\u062f\u0629 \u0643\u0645\u0644\u062a \u0623\u0643\u062b\u0631 \u0645\u0646 \u062b\u0644\u0627\u062b\u0629 \u0623\u0633\u0627\u0628\u064a\u0639 \u0631\u063a\u0645 \u0623\u0646\u0643 \u062a\u0627\u062e\u0630 \u0627\u0644\u062f\u0648\u0627\u0621 \u0645\u0639 \u0627\u0644\u0623\u0643\u0644\u0629\u060c \u0627\u0644\u0637\u0628\u064a\u0628 \u064a\u0642\u062f\u0631 \u064a\u0628\u062f\u0644 \u0627\u0644\u062c\u0631\u0639\u0629 \u0634\u0648\u064a\u0629 \u0634\u0648\u064a\u0629 \u0623\u0648 \u064a\u0639\u0637\u064a\u0643 \u0646\u0648\u0639 \u0622\u062e\u0631 \u0645\u0646 \u0627\u0644\u062f\u0648\u0627\u0621 \u0623\u0633\u0647\u0644 \u0639\u0644\u0649 \u0627\u0644\u0645\u0639\u062f\u0629.\n"
    "\n"
    "TITRE: Signes d'une reaction grave necessitant un arret immediat\n"
    "Il faut arreter le medicament et consulter en urgence en cas de:\n"
    "difficulte a respirer, gonflement du visage ou de la gorge, eruption\n"
    "cutanee etendue, douleurs musculaires severes inexpliquees, ou\n"
    "faiblesse extreme avec respiration rapide. Ces signes sont rares mais\n"
    "serieux.\n"
    "DARIJA: \u0644\u0627\u0632\u0645 \u062a\u0648\u0642\u0641 \u0627\u0644\u062f\u0648\u0627\u0621 \u0648\u062a\u0634\u0648\u0641 \u0637\u0648\u0627\u0631\u0626 \u0643\u0627\u0646 \u0635\u0627\u0631 \u0639\u0646\u062f\u0643: \u0635\u0639\u0648\u0628\u0629 \u0641\u064a \u0627\u0644\u062a\u0646\u0641\u0633\u060c \u062a\u0648\u0631\u0645 \u0641\u064a \u0627\u0644\u0648\u062c\u0647 \u0623\u0648 \u0627\u0644\u062d\u0644\u0642\u060c \u0637\u0641\u062d \u0643\u0628\u064a\u0631 \u0641\u064a \u0627\u0644\u062c\u0644\u062f\u060c \u0623\u0648 \u0648\u062c\u0639 \u0639\u0636\u0644\u064a \u0642\u0648\u064a \u0645\u0639 \u062a\u0646\u0641\u0633 \u0633\u0631\u064a\u0639. \u0647\u0630\u0648\u0645 \u0627\u0644\u0639\u0644\u0627\u0645\u0627\u062a \u0646\u0627\u062f\u0631\u0629 \u0628\u0633 \u062e\u0637\u064a\u0631\u0629.\n"
    "\n"
    "TITRE: Risque de carence en vitamine B12\n"
    "Un traitement prolonge par metformine peut parfois reduire l'absorption\n"
    "de la vitamine B12. Un controle sanguin periodique (une fois par an\n"
    "environ) est souvent recommande pour les patients sous traitement\n"
    "depuis plusieurs annees.\n"
    "DARIJA: \u0627\u0644\u0639\u0644\u0627\u062c \u0627\u0644\u0637\u0648\u064a\u0644 \u0628\u0627\u0644\u0645\u062a\u0641\u0648\u0631\u0645\u064a\u0646 \u0645\u0645\u0643\u0646 \u064a\u0646\u0642\u0635 \u0641\u064a\u062a\u0627\u0645\u064a\u0646 B12 \u0641\u064a \u0627\u0644\u062c\u0633\u0645. \u0623\u062d\u0633\u0646\u0644\u0643 \u062a\u062f\u064a\u0631 \u062a\u062d\u0644\u064a\u0644 \u062f\u0645 \u0645\u0631\u0629 \u0641\u064a \u0627\u0644\u0639\u0627\u0645 \u0643\u0627\u0646 \u0631\u0627\u0643 \u062a\u0627\u062e\u0630 \u0627\u0644\u062f\u0648\u0627\u0621 \u0645\u0646 \u0628\u0631\u0634\u0627 \u0639\u0627\u0645.\n"
)

content_map["exercise_detailed.txt"] = (
    "TITRE: Types d'activite physique recommandes\n"
    "La marche rapide, le velo, et la natation sont de bons choix pour les\n"
    "diabetiques: ils sont faciles a doser en intensite et a faible impact.\n"
    "L'objectif habituel est environ 150 minutes par semaine, reparties sur\n"
    "plusieurs jours plutot qu'en une seule fois.\n"
    "DARIJA: \u0627\u0644\u0645\u0634\u064a \u0628\u0633\u0631\u0639\u0629\u060c \u0627\u0644\u062f\u0631\u0627\u062c\u0629\u060c \u0648\u0627\u0644\u0639\u0648\u0645 \u0645\u0646 \u0623\u062d\u0633\u0646 \u0627\u0644\u0631\u064a\u0627\u0636\u0627\u062a \u0644\u0644\u0633\u0643\u0631\u064a. \u0627\u0644\u0647\u062f\u0641 \u0627\u0644\u0639\u0627\u0645 \u0647\u0648 150 \u062f\u0642\u064a\u0642\u0629 \u0641\u064a \u0627\u0644\u062c\u0645\u0639\u0629\u060c \u0645\u0642\u0633\u0645\u0629 \u0639\u0644\u0649 \u0628\u0631\u0634\u0629 \u0623\u064a\u0627\u0645 \u0645\u0648\u0634 \u0646\u0647\u0627\u0631 \u0648\u0627\u062d\u062f.\n"
    "\n"
    "TITRE: Precautions avant l'effort\n"
    "Si la glycemie est inferieure a 1.00 g/L avant l'effort, il est\n"
    "conseille de manger une petite collation. Si elle depasse 2.50 g/L,\n"
    "il vaut mieux reporter l'effort et consulter si cela se repete. Toujours\n"
    "avoir une source de sucre rapide a portee de main pendant l'exercice.\n"
    "DARIJA: \u0643\u0627\u0646 \u0627\u0644\u0633\u0643\u0631 \u062a\u062d\u062a 1.00 \u0642\u0628\u0644 \u0627\u0644\u0631\u064a\u0627\u0636\u0629\u060c \u0643\u0648\u0644 \u0634\u064a \u062e\u0641\u064a\u0641 \u0642\u0628\u0644 \u0645\u0627 \u062a\u0628\u062f\u0627. \u0643\u0627\u0646 \u0641\u0648\u0642 2.50\u060c \u0623\u062d\u0633\u0646\u0644\u0643 \u062a\u0623\u062c\u0644 \u0627\u0644\u0631\u064a\u0627\u0636\u0629. \u062f\u064a\u0645\u0627 \u062e\u0644\u064a \u0645\u0639\u0627\u0643 \u0634\u064a \u062d\u0627\u062c\u0629 \u0641\u064a\u0647\u0627 \u0633\u0643\u0631 \u0633\u0631\u064a\u0639 \u0648\u0642\u062a \u0627\u0644\u0631\u064a\u0627\u0636\u0629.\n"
)

content_map["travel_and_medication.txt"] = (
    "TITRE: Voyager avec son traitement\n"
    "Garder le medicament dans son emballage d'origine avec l'ordonnance,\n"
    "en bagage a main plutot qu'en soute pour eviter les pertes. Prevoir une\n"
    "quantite superieure a la duree du voyage en cas de retard. Pour un vol,\n"
    "une ordonnance ou un certificat medical peut etre demande au controle.\n"
    "DARIJA: \u062e\u0644\u064a \u0627\u0644\u062f\u0648\u0627\u0621 \u0641\u064a \u0639\u0644\u0628\u062a\u0647 \u0627\u0644\u0623\u0635\u0644\u064a\u0629 \u0645\u0639 \u0627\u0644\u0648\u0635\u0641\u0629\u060c \u0648\u062e\u0630\u064a\u0647 \u0645\u0639\u0627\u0643 \u0641\u064a \u0627\u0644\u0634\u0646\u0637\u0629 \u0627\u0644\u064a\u062f\u0648\u064a\u0629 \u0645\u0648\u0634 \u0641\u064a \u0627\u0644\u0634\u0646\u0637\u0629 \u0627\u0644\u0643\u0628\u064a\u0631\u0629. \u062e\u0630 \u0643\u0645\u064a\u0629 \u0632\u064a\u0627\u062f\u0629 \u0639\u0644\u0649 \u0645\u062f\u0629 \u0627\u0644\u0633\u0641\u0631\u0629 \u062a\u062d\u0633\u0628\u0627 \u0644\u0623\u064a \u062a\u0623\u062e\u064a\u0631. \u0641\u064a \u0627\u0644\u0637\u064a\u0627\u0631\u0629\u060c \u0645\u0645\u0643\u0646 \u064a\u0637\u0644\u0628\u0648\u0627 \u0645\u0646\u0643 \u0627\u0644\u0648\u0635\u0641\u0629.\n"
    "\n"
    "TITRE: Decalage horaire et prises du medicament\n"
    "Pour un voyage avec decalage horaire important, il est conseille de\n"
    "demander conseil au medecin avant le depart pour adapter les horaires\n"
    "de prise progressivement plutot que de changer brutalement.\n"
    "DARIJA: \u0643\u0627\u0646 \u0631\u0627\u0643 \u0645\u0633\u0627\u0641\u0631 \u0644\u0628\u0644\u0627\u0635\u0629 \u0641\u064a\u0647\u0627 \u0641\u0631\u0642 \u062a\u0648\u0642\u064a\u062a \u0643\u0628\u064a\u0631\u060c \u0623\u062d\u0633\u0646\u0644\u0643 \u062a\u0633\u0623\u0644 \u0637\u0628\u064a\u0628\u0643 \u0642\u0628\u0644 \u0627\u0644\u0633\u0641\u0631 \u0628\u0627\u0634 \u062a\u0639\u0631\u0641 \u0643\u064a\u0641\u0627\u0634 \u062a\u0628\u062f\u0644 \u0627\u0644\u062a\u0648\u0642\u064a\u062a \u0634\u0648\u064a\u0629 \u0634\u0648\u064a\u0629 \u0645\u0648\u0634 \u0628\u0627\u0644\u063a\u0644\u0637.\n"
)

content_map["drug_interactions.txt"] = (
    "TITRE: Interaction avec d'autres medicaments pour le diabete\n"
    "La combinaison de la metformine avec d'autres traitements du diabete\n"
    "(comme l'insuline ou d'autres comprimes) est courante et se fait sous\n"
    "surveillance medicale. Ne jamais ajouter ou combiner des traitements\n"
    "sans l'avis du medecin, meme s'ils sont en vente libre.\n"
    "DARIJA: \u062e\u0644\u0637 \u0627\u0644\u0645\u062a\u0641\u0648\u0631\u0645\u064a\u0646 \u0645\u0639 \u0623\u062f\u0648\u064a\u0629 \u0623\u062e\u0631\u0649 \u0644\u0644\u0633\u0643\u0631\u064a \u0634\u064a \u0639\u0627\u062f\u064a \u0628\u0633 \u0644\u0627\u0632\u0645 \u062a\u0643\u0648\u0646 \u062a\u062d\u062a \u0645\u0631\u0627\u0642\u0628\u0629 \u0637\u0628\u064a\u0628\u0643. \u0645\u0627 \u062a\u0632\u064a\u062f\u0634 \u0623\u064a \u062f\u0648\u0627\u0621 \u0648\u062d\u062f\u0643 \u0628\u0644\u0627 \u0645\u0627 \u062a\u0633\u0623\u0644 \u0627\u0644\u0637\u0628\u064a\u0628\u060c \u062d\u062a\u0649 \u0643\u0627\u0646 \u0645\u0648\u062c\u0648\u062f \u0628\u0644\u0627 \u0648\u0635\u0641\u0629.\n"
    "\n"
    "TITRE: Produits dont il faut parler avant un examen medical\n"
    "Avant un examen avec produit de contraste iode (scanner par exemple),\n"
    "il faut signaler la prise de metformine, car le medicament doit parfois\n"
    "etre interrompu temporairement autour de l'examen sur avis medical.\n"
    "DARIJA: \u0642\u0628\u0644 \u0623\u064a \u0641\u062d\u0635 \u0641\u064a\u0647 \u062d\u0642\u0646\u0629 \u0636\u062f \u0627\u0644\u0635\u0628\u063a\u0629 (\u0645\u062b\u0644 \u0627\u0644\u0633\u0643\u0627\u0646\u0631)\u060c \u0642\u0648\u0644 \u0644\u0644\u0637\u0628\u064a\u0628 \u0625\u0646\u0643 \u062a\u0627\u062e\u0630 \u0627\u0644\u0645\u062a\u0641\u0648\u0631\u0645\u064a\u0646\u060c \u0644\u0623\u0646 \u0645\u0645\u0643\u0646 \u064a\u0642\u0648\u0644\u0643 \u062a\u0648\u0642\u0641 \u0627\u0644\u062f\u0648\u0627\u0621 \u0634\u0648\u064a\u0629 \u0642\u0628\u0644 \u0648\u0628\u0639\u062f \u0627\u0644\u0641\u062d\u0635.\n"
)

for name, content in content_map.items():
    path = KB_DIR / name
    path.write_text(content, encoding="utf-8")
    print(f"Written {name}: {content.count('TITRE:')} TITRE blocks")